raw:
{
  "story": "Mitosis replicates a cell into two identical daughter cells through coordinated steps. Chromosomes condense, align at the center, separate to opposite poles, and finally the cell divides completely.",
  "aha": {
    "stateId": "anaphase",
    "observation": "Sister chromatids split apart and migrate toward opposing spindle poles, doubling the genetic material count at each side."
  },
  "layout": {
    "preset": "stepper-card",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "picture",
      "kind": "fixed-picture",
      "bind": {
        "active": "inputs.stepIndex",
        "regions": "variant.regions",
        "values": "state.active"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "ghost",
      "kind": "previous-state-ghost",
      "bind": {
        "regions": "previous.regions"
      }
    },
    {
      "id": "readouts",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    },
    {
      "id": "prog",
      "kind": "progress",
      "bind": {
        "completedBefore": "inputs.stepIndex"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Mitosis Step",
      "options": [
        "prophase",
        "metaphase",
        "anaphase",
        "telophase"
      ]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset"
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Standard Mitosis Cycle",
        "regions": [
          {
            "id": "chromosomes",
            "label": "Chromosomes",
            "kind": "DNA",
            "phases": ["condensing", "aligned", "separating", "decondensing"]
          },
          {
            "id": "spindle",
            "label": "Spindle Fibers",
            "kind": "Cytoskeleton",
            "phases": ["forming", "attached", "pulling", "dissolving"]
          },
          {
            "id": "membrane",
            "label": "Nuclear Envelope",
            "kind": "Barrier",
            "phases": ["breaking down", "absent", "absent", "reforming"]
          }
        ],
        "states": [
          {
            "id": "prophase",
            "label": "Prophase",
            "short": "Condense",
            "sentence": "Chromatin condenses into visible chromosomes and the nuclear envelope breaks down.",
            "why": "Preparation for orderly DNA distribution.",
            "active": ["chromosomes", "membrane"],
            "calloutRegion": "chromosomes",
            "readouts": [
              {
                "id": "chromCount",
                "label": "Chromosomes",
                "value": "46 duplicated"
              },
              {
                "id": "ploidy",
                "label": "Ploidy",
                "value": "2N (96 chromatids)"
              }
            ]
          },
          {
            "id": "metaphase",
            "label": "Metaphase",
            "short": "Align",
            "sentence": "Chromosomes align along the metaphase plate, attached to spindle fibers.",
            "why": "Ensures equal segregation in the next phase.",
            "active": ["chromosomes", "spindle"],
            "calloutRegion": "chromosomes",
            "readouts": [
              {
                "id": "chromCount",
                "label": "Chromosomes",
                "value": "Aligned at center"
              },
              {
                "id": "ploidy",
                "label": "Ploidy",
                "value": "2N checkpoint passed"
              }
            ]
          },
          {
            "id": "anaphase",
            "label": "Anaphase",
            "short": "Separate",
            "sentence": "Sister chromatids are pulled apart toward opposite poles by shortening spindle fibers.",
            "why": "Genetic material is equally divided.",
            "active": ["chromosomes", "spindle"],
            "calloutRegion": "chromosomes",
            "readouts": [
              {
                "id": "chromCount",
                "label": "Chromatids",
                "value": "46 moving each way"
              },
              {
                "id": "ploidy",
                "label": "Ploidy",
                "value": "Separating"
              }
            ]
          },
          {
            "id": "telophase",
            "label": "Telophase",
            "short": "Divide",
            "sentence": "Two new nuclear envelopes form around the separated sets and chromosomes decondense.",
            "why": "Restores resting state for two independent cells.",
            "active": ["chromosomes", "membrane"],
            "calloutRegion": "membrane",
            "readouts": [
              {
                "id": "chromCount",
                "label": "Nuclei",
                "value": "2 nuclei forming"
              },
              {
                "id": "ploidy",
                "label": "Ploidy",
                "value": "2 x (2N)"
              }
            ]
          }
        ]
      }
    ]
  }
}
